 1→#!/usr/bin/env bun
 2→/**
 3→ * Kspec Daemon Entry Point
 4→ *
 5→ * Long-running server that exposes kspec state via HTTP API and WebSocket.
 6→ * Supports foreground and background modes with PID file management.
 7→ * AC: @daemon-server ac-9
 8→ */
 9→
10→import { createServer } from './server.js';
11→import { parseArgs } from 'util';
12→import { join } from 'path';
13→
14→// Parse command line args
15→const { values } = parseArgs({
16→  args: process.argv.slice(2),
17→  options: {
18→    port: { type: 'string', default: '3456' },
19→    'kspec-dir': { type: 'string' }
20→  },
21→  allowPositionals: true
22→});
23→
24→const port = parseInt(values.port as string, 10);
25→const kspecDir = (values['kspec-dir'] as string) || join(process.cwd(), '.kspec');
26→
27→// Validate port
28→if (isNaN(port) || port < 1 || port > 65535) {
29→  console.error('[daemon] Invalid port number. Must be between 1 and 65535.');
30→  process.exit(1);
31→}
32→
33→async function main() {
34→  try {
35→    console.log(`[daemon] Starting kspec daemon on port ${port}...`);
36→
37→    const server = await createServer({
38→      port,
39→      isDaemon: true, // Always true when running as standalone daemon
40→      kspecDir
41→    });
42→
43→    // Server will start listening in createServer
44→    // Graceful shutdown handled in server.ts
45→
46→  } catch (error) {
47→    console.error('[daemon] Failed to start:', error);
48→    process.exit(1);
49→  }
50→}
51→
52→main();
