296→        }
297→      } else {
298→        orphanedSpecs++;
299→      }
300→    }
301→
302→    return {
303→      totalSpecs: this.specItems.size,
304→      specsWithTasks,
305→      alignedSpecs,
306→      orphanedSpecs,
307→    };
308→  }
309→}
