export async function fetchTasks(params?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<PaginatedResponse<TaskSummary>> {
  // Static mode fallback
  if (isStaticMode()) {
    return fetchTasksStatic(params);
  }

  const url = new URL(`${API_BASE}/api/tasks`);
  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== '') {
        url.searchParams.set(key, String(value));
      }
    });
  }

  const response = await fetch(url.toString(), {
    headers: getProjectHeaders() // Injects X-Kspec-Dir header
  });

  if (!response.ok) {
    await handleResponseError(response);
  }

  return response.json();
}
```

**For write operations, check static mode:**
```ts
export async function addTaskNote(ref: string, content: string): Promise<void> {
  assertWritable('add note'); // Throws ReadOnlyModeError if static

  const response = await fetch(`${API_BASE}/api/tasks/${ref}/note`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...getProjectHeaders()
    },
    body: JSON.stringify({ content })
  });

  if (!response.ok) {
    await handleResponseError(response);
  }
}
```

